/** Deterministic capability ports + production registry/service/tools/agent. Does not launch Minecraft. */
public final class MachineTests {
    static int passed;
    static final UUID OWNER=UUID.fromString("00000000-0000-0000-0000-000000000001");
    static void check(boolean b,String name){if(!b)throw new AssertionError(name);passed++;}
    static void denied(Runnable r,String name){try{r.run();throw new AssertionError(name);}catch(RuntimeException good){passed++;}}
    static JsonObject json(String s){return JsonParser.parseString(s).getAsJsonObject();}
    static JsonObject target(int x){return json("{\"type\":\"block\",\"dimension\":\"minecraft:overworld\",\"x\":"+x+",\"y\":64,\"z\":0,\"side\":\"auto\"}");}
    static JsonObject transfer(String tool,boolean preview){var a=new JsonObject();a.add("from",target(0));a.add("to",target(1));a.addProperty("amount",8);a.addProperty("preview",preview);if(!tool.equals("transfer_energy")){a.addProperty("from_slot",-1);a.addProperty("to_slot",-1);}return a;}
    static JsonObject inspect(){var a=new JsonObject();a.add("target",target(0));a.addProperty("offset",0);a.addProperty("limit",4);return a;}
    static JsonObject named(){return json("{\"project\":\"default\",\"name\":\"feed\"}");}
    static String recipe(int version,boolean predicate){var step=new JsonObject();step.addProperty("tool","transfer_items");step.add("args",transfer("transfer_items",false));step.addProperty("repeat",3);if(predicate){var w=new JsonObject();w.addProperty("tool","machine_inspect");w.add("args",inspect());w.addProperty("path","amount");w.addProperty("op","gt");w.addProperty("value",0);step.add("when",w);}var steps=new JsonArray();steps.add(step);var r=new JsonObject();r.addProperty("version",version);r.add("steps",steps);return r.toString();}
    static final class FakePort implements CapabilityTransfer.Port {
        int stored,capacity=100,extractLimit=100,receiveLimit=100,actualReceiveLimit=100;boolean extract=true,receive=true;String identity="minecraft:iron{grade:1}";
        FakePort(int n){stored=n;}
        public int extract(int n,boolean sim){int moved=extract?Math.min(n,Math.min(stored,extractLimit)):0;if(!sim)stored-=moved;return moved;}
        public int receive(int n,boolean sim){int moved=receive?Math.min(n,Math.min(capacity-stored,sim?receiveLimit:Math.min(receiveLimit,actualReceiveLimit))):0;if(!sim)stored+=moved;return moved;}
    }
    /** Slot/tank fake with exact resource identity (including full tag text), separate from FE. */
    static final class FakeInventory {
        final String[] identities;final int[] quantities;final int capacity;boolean writable=true,extractable=true;
        FakeInventory(int slots,int capacity){identities=new String[slots];quantities=new int[slots];this.capacity=capacity;}
        CapabilityTransfer.Port port(int slot,String identity){return new CapabilityTransfer.Port(){
            public int extract(int n,boolean sim){if(!extractable||!identity.equals(identities[slot]))return 0;int moved=Math.min(n,quantities[slot]);if(!sim)quantities[slot]-=moved;return moved;}
            public int receive(int n,boolean sim){if(!writable||quantities[slot]>0&&!identity.equals(identities[slot]))return 0;int moved=Math.min(n,capacity-quantities[slot]);if(!sim&&moved>0){identities[slot]=identity;quantities[slot]+=moved;}return moved;}
        };}
    }
    static final class FakeTanks {
        final FakeInventory tanks=new FakeInventory(2,1000);
        CapabilityTransfer.Port fluid(int tank,String idAndTags){return tanks.port(tank,idAndTags);}
    }
    static void identities(){
        String a="minecraft:iron_ingot{quality:1}",b="minecraft:iron_ingot{quality:2}";var from=new FakeInventory(2,64);var to=new FakeInventory(2,64);from.identities[0]=a;from.quantities[0]=20;from.identities[1]=b;from.quantities[1]=30;to.identities[0]=b;to.quantities[0]=5;
        check(CapabilityTransfer.move(from.port(0,a),to.port(0,a),8,false,n->{}).moved()==0,"same item ID different NBT cannot merge");check(from.quantities[0]==20&&from.quantities[1]==30,"wrong tagged identity did not extract");var p=CapabilityTransfer.move(from.port(0,a),to.port(1,a),8,true,n->{});check(p.simulated()==8&&to.quantities[1]==0&&to.identities[1]==null,"inventory simulate does not write empty slot identity");var r=CapabilityTransfer.move(from.port(0,a),to.port(1,a),8,false,n->{});check(r.moved()==8&&to.identities[1].equals(a)&&from.quantities[0]==12,"fake inventory slot preserves NBT identity");to.writable=false;check(CapabilityTransfer.move(from.port(0,a),to.port(1,a),8,false,n->{}).moved()==0,"fake inventory rejects insertion");
        var producer=new FakeTanks();var consumer=new FakeTanks();String hot="test:coolant{temperature:400}",cold="test:coolant{temperature:100}";producer.tanks.identities[0]=hot;producer.tanks.quantities[0]=500;consumer.tanks.identities[0]=cold;consumer.tanks.quantities[0]=200;
        check(CapabilityTransfer.move(producer.fluid(0,hot),consumer.fluid(0,hot),100,false,n->{}).moved()==0,"same fluid different tags does not mix");consumer.tanks.quantities[1]=950;consumer.tanks.identities[1]=hot;var fill=CapabilityTransfer.move(producer.fluid(0,hot),consumer.fluid(1,hot),100,false,n->{});check(fill.moved()==50&&producer.tanks.quantities[0]==450&&consumer.tanks.quantities[1]==1000,"fake tank capacities and tagged fluid conserved");producer.tanks.extractable=false;check(CapabilityTransfer.move(producer.fluid(0,hot),consumer.fluid(0,hot),100,true,n->{}).simulated()==0,"non-drainable fake tank stays intact");
    }
    static void ports(){
        for(String kind:List.of("inventory/NBT","tank/fluid-tag","energy/FE")){var from=new FakePort(50);var to=new FakePort(0);int[] held={0};from.extractLimit=12;to.receiveLimit=7;var p=CapabilityTransfer.move(from,to,30,true,n->held[0]+=n);check(p.simulated()==7&&from.stored==50&&to.stored==0,kind+" preview is inert");var r=CapabilityTransfer.move(from,to,30,false,n->held[0]+=n);check(r.moved()==7&&from.stored+to.stored+held[0]==50,kind+" respects throughput and conservation");to.actualReceiveLimit=2;var shortCommit=CapabilityTransfer.move(from,to,7,false,n->held[0]+=n);check(shortCommit.moved()==2&&shortCommit.refunded()==5,kind+" simulation drift compensated");from.receive=false;var escrow=CapabilityTransfer.move(from,to,7,false,n->held[0]+=n);check(escrow.held()==5&&from.stored+to.stored+held[0]==50,kind+" producer refusing refund retains remainder");from.extract=false;check(CapabilityTransfer.move(from,to,8,false,n->held[0]+=n).moved()==0,kind+" extract denied");check(from.identity.equals("minecraft:iron{grade:1}"),kind+" original identity retained");}
        var bad=new FakePort(10);CapabilityTransfer.Port impossible=new CapabilityTransfer.Port(){public int extract(int n,boolean s){return n+1;}public int receive(int n,boolean s){return n;}};denied(()->CapabilityTransfer.move(impossible,bad,1,false,n->{}),"reject lying quantity");
    }
    static final class Backend implements MachineAdapters.Backend {
        final Thread main=Thread.currentThread();int amount=20,moved,reads;boolean loaded=true;
        public JsonObject execute(UUID owner,String tool,JsonObject a){check(Thread.currentThread()==main,"main-thread backend");MachineTools.validate(tool,a);if(!loaded)throw new MachineAdapters.WaitingChunk("WAITING_CHUNK fake");var o=new JsonObject();if(tool.equals("machine_inspect")){reads++;o.addProperty("amount",amount);o.addProperty("status","OBSERVED_SERVER_MAIN");return o;}if(tool.startsWith("transfer_")){int n=Math.min(amount,a.get("amount").getAsInt());if(!a.get("preview").getAsBoolean()){amount-=n;moved+=n;}o.addProperty("moved",a.get("preview").getAsBoolean()?0:n);o.addProperty("simulated",n);o.addProperty("status",a.get("preview").getAsBoolean()?"SIMULATED":"EXECUTED_SERVER_MAIN");return o;}throw new IllegalArgumentException("fake unsupported");}
    }
    static JsonObject create(int version){var c=named();c.addProperty("source",recipe(version,true));return c;}
    static JsonObject execute(boolean preview){var e=named();e.addProperty("preview",preview);return e;}
    static JsonObject project(){return json("{\"project\":\"default\"}");}
    static void adapters(Path root)throws Exception {
        var b=new Backend();var r=new MachineAdapters(root,b);r.command(OWNER,"adapter_create",create(1));check(r.command(OWNER,"adapter_list",project()).getAsJsonArray("active").size()==1,"created and active via tool args");r.command(OWNER,"adapter_execute",execute(true));for(int i=0;i<3;i++)r.tick();check(b.moved==0&&r.status(OWNER,"default").get("status").getAsString().equals("COMPLETED"),"pipeline preview read/simulate only");
        r.command(OWNER,"adapter_execute",execute(false));b.loaded=false;r.tick();check(r.status(OWNER,"default").get("status").getAsString().equals("WAITING_CHUNK")&&b.moved==0,"unloaded waits without advancing");b.loaded=true;for(int i=0;i<3;i++)r.tick();check(b.moved==20&&b.amount==0,"finite repeat real transfer with live predicate");
        var changed=json(recipe(1,true));changed.getAsJsonArray("steps").get(0).getAsJsonObject().addProperty("repeat",4);var c=named();c.addProperty("source",changed.toString());denied(()->{try{r.command(OWNER,"adapter_create",c);}catch(Exception e){throw new RuntimeException(e);}},"changed same-version rejected");r.command(OWNER,"adapter_create",create(2));Path file=root.resolve(OWNER.toString()).resolve("default/feed.adapter.json");Files.writeString(file,"{}");denied(()->{try{r.command(OWNER,"adapter_load",named());}catch(Exception e){throw new RuntimeException(e);}},"invalid reload rejected");check(r.command(OWNER,"adapter_list",project()).getAsJsonArray("active").get(0).getAsJsonObject().get("version").getAsInt()==2,"invalid reload retains last good");r.command(OWNER,"adapter_execute",execute(false));r.tick();check(r.status(OWNER,"default").get("skipped").getAsInt()==1,"predicate re-evaluated live and skipped");r.command(OWNER,"adapter_cancel",project());check(r.status(OWNER,"default").get("status").getAsString().equals("CANCELLED"),"cancel remainder");
        Files.writeString(file,recipe(3,true));r.command(OWNER,"adapter_load",named());check(r.command(OWNER,"adapter_list",project()).getAsJsonArray("active").get(0).getAsJsonObject().get("version").getAsInt()==3,"load replaces session without restart");var fresh=new MachineAdapters(root,b);fresh.command(OWNER,"adapter_execute",execute(true));check(fresh.status(OWNER,"default").get("version").getAsInt()==3,"saved recipe lazy-load after restart");
        denied(()->MachineAdapters.validate(recipe(1,true).replace("transfer_items","start_machine")),"unknown operation rejected");denied(()->MachineAdapters.validate(recipe(1,true).replace("\"repeat\":3","\"repeat\":257")),"repeat budget rejected");denied(()->MachineAdapters.validate(recipe(1,true).replace("\"amount\":8","\"amount\":0")),"actual schemas validate pipeline quantity");denied(()->MachineAdapters.validate(recipe(1,true).replace("\"version\":1","\"version\":1,\"version\":2")),"duplicate source keys rejected");
    }
    static final class Host implements GameService.Host {
        final Queue<Runnable> tasks=new ConcurrentLinkedQueue<>();final Backend b=new Backend();final List<String> messages=new ArrayList<>();boolean online=true;
        public void main(Runnable r){tasks.add(r);}public boolean online(UUID id){return online;}public void message(UUID id,String s){messages.add(s);}public void particles(UUID id,String shape,int radius){}public List<String> mods(){return List.of();}public String loader(){return "forge";}public JsonObject machineOperation(UUID id,String tool,JsonObject args){return b.execute(id,tool,args);}void drain(){Runnable r;while((r=tasks.poll())!=null)r.run();}
    }
    static NaniteSession detached(){return new NaniteSession(OWNER.toString(),GameService.POLICY,List.of(new Ledger.Reservoir("storage","generic",100)),Map.of("storage",0L),"test.nano","program test version v1; state hits = 0;");}
    static void pump(Host host,Future<?> f)throws Exception {long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(!f.isDone()&&System.nanoTime()<deadline){host.drain();Thread.yield();}check(f.isDone(),"tool protocol finished");}
    static void service(Path root)throws Exception {
        var h=new Host();try(var s=new GameService(root.resolve("world"),root.resolve("config"),h)){
            s.login(OWNER);var gateway=s.machineGateway(OWNER);var f=gateway.execute("transfer_items",transfer("transfer_items",false));check(!f.isDone()&&h.b.moved==0,"gateway marshals operation");h.drain();check(f.join().get("moved").getAsInt()==8,"gateway actually mutates without grant");var cancelled=gateway.execute("transfer_items",transfer("transfer_items",false));cancelled.cancel(false);h.drain();check(h.b.moved==8,"cancelled pending callback has no effect");s.command(OWNER,"machine_inspect "+inspect());check(h.messages.get(h.messages.size()-1).contains("OBSERVED_SERVER_MAIN"),"manual command uses same backend");
            var tools=new ControlledTools(new SourceCache(root.resolve("cache")),Map.of(),new JsonObject(),detached(),OWNER.toString(),MachineTools.NAMES,s.machineGateway(OWNER));check(tools.definitions().size()==MachineTools.NAMES.size(),"all tools exposed actual schemas");
            var fullNames=new HashSet<>(MachineTools.NAMES);fullNames.addAll(ControlledTools.NAMES);fullNames.addAll(ControlledTools.WORLD_TOOLS);fullNames.addAll(ControlledTools.MUTATIONS);var fullTools=new ControlledTools(new SourceCache(root.resolve("full-cache")),Map.of(),new JsonObject(),detached(),OWNER.toString(),fullNames,s.machineGateway(OWNER));check(fullTools.definitions().size()==LocalChatClient.toolCeiling(),"31 existing plus machine/runtime tool schemas preserved");
            try(var protocol=new LocalChatClient(new LocalChatClient.Config(IntegrationContracts.LOCAL_AI,"fake",Duration.ofSeconds(5),64,131072,1),(uri,body,timeout,max)->{check(json(new String(body,StandardCharsets.UTF_8)).getAsJsonArray("tools").size()==LocalChatClient.toolCeiling(),"client transmits complete Forge schema set");return CompletableFuture.completedFuture(new LocalChatClient.Response(200,"{}".getBytes(StandardCharsets.UTF_8)));})){check(protocol.complete(new JsonArray(),fullTools.definitions()).get().isJsonObject(),"expanded schemas do not hit former 16-tool ceiling");}
            var calls=List.of("adapter_create","adapter_execute","adapter_status","machine_inspect");int[] turns={0};LocalChatClient.Transport transport=(uri,body,timeout,max)->{
                int n=turns[0]++;String request=new String(body,StandardCharsets.UTF_8);if(n>0)check(request.contains("tool_call_id"),"multi-turn receives server receipts");if(n==1){check(request.contains("QUEUED"),"queued is not completion");h.tasks.add(()->{for(int i=0;i<3;i++)s.serverTick();});}if(n==2)check(request.contains("COMPLETED"),"next turn sees actual executor completion");
                var message=new JsonObject();message.addProperty("role","assistant");message.addProperty("content",n<2?"":"done from observed effects");var choice=new JsonObject();choice.addProperty("finish_reason",n<2?"tool_calls":"stop");
                if(n<2){var ca=new JsonArray();for(int index=n*2;index<n*2+2;index++){String name=calls.get(index);var fn=new JsonObject();fn.addProperty("name",name);JsonObject args=index==0?create(1):index==1?execute(false):index==2?project():inspect();fn.addProperty("arguments",args.toString());var call=new JsonObject();call.addProperty("id","machine"+index);call.addProperty("type","function");call.add("function",fn);ca.add(call);}message.add("tool_calls",ca);}choice.add("message",message);var choices=new JsonArray();choices.add(choice);var response=new JsonObject();response.add("choices",choices);return CompletableFuture.completedFuture(new LocalChatClient.Response(200,response.toString().getBytes(StandardCharsets.UTF_8)));
            };
            try(var client=new LocalChatClient(new LocalChatClient.Config(IntegrationContracts.LOCAL_AI,"fake",Duration.ofSeconds(5),64,131072,1),transport);var agent=new MultiTurnAgent(client)){var run=agent.run("create and activate feed adapter",tools,new MultiTurnAgent.Limits(6,8,MultiTurnAgent.catalogBudget(client,tools.definitions(),6),65536),t->{});pump(h,run);check(run.get().calls()==4&&turns[0]==3,"AI generates creates executes and observes adapter in multiple turns");check(h.b.moved==20,"AI pipeline connected to real shared executor");}
            var liveTools=new ControlledTools(new SourceCache(root.resolve("live-cache")),Map.of(),new JsonObject(),detached(),OWNER.toString(),Set.of("catalog","state"),null).live(s.liveProvider(OWNER)).extensions(s.machineLiveProvider(OWNER));var worker=Executors.newSingleThreadExecutor();try{var before=worker.submit(()->liveTools.invoke("catalog","{}"));pump(h,before);check(json(before.get()).getAsJsonObject("data").getAsJsonObject("machine_live").getAsJsonObject("job").get("status").getAsString().equals("COMPLETED"),"catalog extension is live after AI pipeline");s.command(OWNER,"adapter_create "+create(2));var after=worker.submit(()->liveTools.invoke("state","{}"));pump(h,after);check(json(after.get()).getAsJsonObject("data").getAsJsonObject("machine_live").getAsJsonArray("adapters").get(0).getAsJsonObject().get("version").getAsInt()==2,"state snapshot sees hot-reloaded adapter in same tool instance");}finally{worker.shutdownNow();}
            var stale=s.machineGateway(OWNER);var late=stale.execute("transfer_items",transfer("transfer_items",false));s.invalidateRuntime(OWNER);h.drain();check(late.isCompletedExceptionally(),"lifecycle invalidates late machine calls");
        }
    }
    public static void main(String[] args)throws Exception {identities();ports();adapters(Files.createTempDirectory("nanites-adapters-"));service(Files.createTempDirectory("nanites-machines-"));System.out.println("MachineTests: "+passed+" checks passed (fake ports/AI, Minecraft NOT launched)");}
}
